import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long x = nextLong(), y = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long delta = x - y, lo = 0, hi = 0;
        for (long v : a) hi += (v + x - 1) / x; // main slot on every task always works
        while (lo < hi) {
            long t = lo + (hi - lo) / 2, need = 0;
            for (long v : a) {
                // t * y may overflow: compare against v first.
                if (y > 0 && t >= (v + y - 1) / y) continue;
                long rest = v - t * y;
                need += (rest + delta - 1) / delta;
                if (need > t) break;
            }
            if (need <= t) hi = t;
            else lo = t + 1;
        }
        System.out.println(lo);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	x, y := nextInt(), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	delta, lo, hi := x-y, int64(0), int64(0)
	for _, v := range a {
		hi += (v + x - 1) / x // main slot on every task always works
	}
	for lo < hi {
		t := lo + (hi-lo)/2
		need := int64(0)
		for _, v := range a {
			// t * y may overflow: compare against v first.
			if y > 0 && t >= (v+y-1)/y {
				continue
			}
			need += (v - t*y + delta - 1) / delta
			if need > t {
				break
			}
		}
		if need <= t {
			hi = t
		} else {
			lo = t + 1
		}
	}
	fmt.Println(lo)
}
